INSERT INTO meetings VALUES ('MTG001', 'Sprint Planning for Enterprise AI Workspace', '2026-01-08', '60 minutes', 'Aarav Menon', 'Rohan Sharma; Ananya Iyer; Vikram Rao; Arjun Patel; Karthik Reddy', 'Finalize sprint scope and assign ownership for authentication, dashboards, and RAG discovery.', 'Sprint 1 will prioritize login, employee dashboard shell, authentication API, and RAG proof of concept.', 'Rohan to prepare vector store plan; Vikram to publish auth API contract; Arjun to start login page.');
INSERT INTO meetings VALUES ('MTG002', 'AI Assistant Architecture Review', '2026-01-24', '75 minutes', 'Aarav Menon', 'Rohan Sharma; Ananya Iyer; Vikram Rao; Meera Krishnan', 'Review AI assistant service boundary, document retrieval, security, and latency targets.', 'Adopt FastAPI service for assistant orchestration and keep document access filtered by role metadata.', 'Ananya to define evaluation set; Meera to add API logging; Rohan to configure ChromaDB collections.');
INSERT INTO meetings VALUES ('MTG003', 'Dashboard Progress Sync', '2026-02-07', '45 minutes', 'Aarav Menon', 'Arjun Patel; Sneha Kulkarni; Vikram Rao; Divya Singh', 'Check employee and manager dashboard progress, data contracts, and blocker list.', 'Manager dashboard will expose completion rate, overdue tasks, and department performance from the same task table.', 'Sneha to finish metric cards; Vikram to add task summary endpoint; Divya to validate label wording.');
INSERT INTO meetings VALUES ('MTG004', 'QA Test Strategy Review', '2026-02-21', '60 minutes', 'Priya Nair', 'Karthik Reddy; Nisha Gupta; Meera Krishnan; Arjun Patel', 'Define QA approach for authentication, dashboards, document retrieval, and regression cycles.', 'Cypress will cover core UI workflows and Postman collections will validate API contracts.', 'Karthik to draft test plan; Nisha to create regression checklist; Meera to share test credentials.');
INSERT INTO meetings VALUES ('MTG005', 'HR Policy Digitization Workshop', '2026-03-05', '50 minutes', 'Priya Nair', 'Farhan Khan; Divya Singh; Rohan Sharma; Ananya Iyer', 'Prepare HR and company policy documents for RAG ingestion and employee self-service.', 'Policies will be chunked by section and tagged by policy type, effective date, and audience.', 'Farhan to finalize leave policy; Divya to standardize document headers; Ananya to test retrieval quality.');
INSERT INTO meetings VALUES ('MTG006', 'Client Feedback Review for Project Alpha', '2026-03-19', '60 minutes', 'Aarav Menon', 'Rohan Sharma; Ananya Iyer; Arjun Patel; Sneha Kulkarni; Karthik Reddy', 'Discuss client feedback on dashboard navigation, assistant response tone, and export requirements.', 'Team will add clearer status filters, export-ready dashboard data, and concise assistant citations.', 'Sneha to update filter design; Rohan to tune assistant prompt; Karthik to add acceptance scenarios.');
INSERT INTO meetings VALUES ('MTG007', 'RAG Module Deep Dive', '2026-04-02', '90 minutes', 'Aarav Menon', 'Rohan Sharma; Ananya Iyer; Vikram Rao; Nisha Gupta', 'Validate ingestion pipeline, embedding metadata, retrieval relevance, and fallback behavior.', 'Use document version metadata to prefer latest approved files while preserving older versions for audit.', 'Ananya to add version-aware retrieval tests; Vikram to expose document list endpoint; Nisha to run query set.');
INSERT INTO meetings VALUES ('MTG008', 'Deployment Readiness Check', '2026-04-23', '60 minutes', 'Aarav Menon', 'Vikram Rao; Meera Krishnan; Karthik Reddy; Divya Singh', 'Review Docker setup, environment variables, rollback plan, and release documentation.', 'Release candidate will deploy to staging after security policy review and QA sign-off.', 'Meera to update compose file; Karthik to publish sign-off report; Divya to prepare release checklist.');
INSERT INTO meetings VALUES ('MTG009', 'Monthly Performance and Workload Review', '2026-05-14', '55 minutes', 'Priya Nair', 'Farhan Khan; Divya Singh; Karthik Reddy; Nisha Gupta; Sneha Kulkarni', 'Review employee workload balance, pending tasks, and support needs.', 'Tasks are evenly distributed, but QA requires two focused regression windows before final demo.', 'Farhan to update workload tracker; Nisha to flag high-risk test cases; Sneha to close dashboard UI issues.');
INSERT INTO meetings VALUES ('MTG010', 'Final Demo Preparation', '2026-06-10', '75 minutes', 'Aarav Menon', 'Rohan Sharma; Ananya Iyer; Vikram Rao; Arjun Patel; Sneha Kulkarni; Karthik Reddy; Farhan Khan', 'Prepare final year project demo flow, data story, known limitations, and presentation sequence.', 'Demo will show login, dashboards, task workflow, document search, AI assistant, and SQL-backed analytics.', 'Rohan to prepare AI demo prompts; Arjun to verify UI flows; Karthik to perform final smoke test.');
